globalThis.KENGURU_CHOICE_LAYOUTS = {"2014-3-4/3":{"options":[{"image":"assets/separated-choices/2014-3-4/03-1.webp","pixelWidth":103,"pixelHeight":104},{"image":"assets/separated-choices/2014-3-4/03-2.webp","pixelWidth":104,"pixelHeight":104},{"image":"assets/separated-choices/2014-3-4/03-3.webp","pixelWidth":104,"pixelHeight":104},{"image":"assets/separated-choices/2014-3-4/03-4.webp","pixelWidth":104,"pixelHeight":104},{"image":"assets/separated-choices/2014-3-4/03-5.webp","pixelWidth":104,"pixelHeight":104}],"condition":{"src":"assets/separated-choices/2014-3-4/03-condition.webp","width":202,"height":203}},"2014-3-4/15":{"options":[{"image":"assets/separated-choices/2014-3-4/15-1.webp","pixelWidth":108,"pixelHeight":156},{"image":"assets/separated-choice-vectors/2014-3-4/15-2.svg"},{"image":"assets/separated-choice-vectors/2014-3-4/15-3.svg"},{"image":"assets/separated-choices/2014-3-4/15-4.webp","pixelWidth":206,"pixelHeight":156},{"image":"assets/separated-choices/2014-3-4/15-5.webp","pixelWidth":157,"pixelHeight":108}],"condition":{"src":"assets/separated-choices/2014-3-4/15-condition.webp","width":111,"height":109}},"2014-3-4/19":{"options":[{"image":"assets/separated-choices/2014-3-4/19-1.webp","pixelWidth":140,"pixelHeight":141},{"image":"assets/separated-choices/2014-3-4/19-2.webp","pixelWidth":141,"pixelHeight":141},{"image":"assets/separated-choices/2014-3-4/19-3.webp","pixelWidth":140,"pixelHeight":140},{"image":"assets/separated-choices/2014-3-4/19-4.webp","pixelWidth":139,"pixelHeight":141},{"image":"assets/separated-choices/2014-3-4/19-5.webp","pixelWidth":139,"pixelHeight":140}]},"2014-3-4/24":{"options":[{"image":"assets/separated-choice-vectors/2014-3-4/24-1.svg"},{"image":"assets/separated-choice-vectors/2014-3-4/24-2.svg"},{"image":"assets/separated-choice-vectors/2014-3-4/24-3.svg"},{"image":"assets/separated-choice-vectors/2014-3-4/24-4.svg"},{"image":"assets/separated-choice-vectors/2014-3-4/24-5.svg"}],"condition":{"src":"assets/separated-choices/2014-3-4/24-condition.webp","width":213,"height":163}}};
globalThis.KENGURU_LEGACY = [[2014,"3–4 классы",[[834,130,"Боря выложил из одинаковых палочек слово КЕНГУРУ. Сколько букв сложены из 5 палочек?",{},"B","Слово из палочек",[["Считай по буквам","Буква К состоит из четырёх палочек, Г и обе буквы У — из трёх каждая."],["Найди пятёрки","По пять палочек понадобилось для Е, Н и Р. Таких букв три."]],""],[834,125,"Как в математике называется число, которое вычитают?",{"0":[51.8,37.5,31.6,26.5],"1":[328.2,37.5,31.6,26.5],"2":[51.8,64,31.6,26.5],"3":[328.2,64,28.8,26.5],"4":[51.8,91.1,31.6,26.5]},"E","Название числа",[["Возьми пример","В записи 9 − 4 = 5 число 4 вычитают из 9."],["Назови число","Число 4 называется вычитаемым. 9 — уменьшаемое, 5 — разность."]],""],[834,236,"(В) вычитываемое (Г) вычитающееся (Д) вычитаемое 3. Как выглядит центральная часть звезды, изображенной на рисунке справа?",{},"D","Середина звезды",[["Посчитай лучи","Мысленно обведи маленький круг с тем же центром. Каждый луч звезды пересечёт этот круг."],["Найди рисунок","У звезды девять лучей. Столько же светлых лучей в варианте Г."]],""],[834,71,"Во сколько раз 10 метров больше 1 мм?",{"0":[51.8,36.9,31.6,26.5],"1":[201.8,36.9,31.6,26.5],"2":[351.8,36.9,31.6,26.5],"3":[501.3,36.9,28.8,26.5],"4":[651.3,36.9,31.6,26.5]},"B","Метры и миллиметры",[["Переведи один метр","В метре 100 сантиметров, а в каждом сантиметре 10 миллиметров. Значит, 1 м = 1000 мм."],["Переведи десять метров","В 10 м ровно 10 000 миллиметров. Это в 10 000 раз больше 1 мм."]],""],[834,184,"Аня хочет вставить цифру 3 в число 2014 так, чтобы получившееся пятизначное число было как можно меньше. Где она должна написать цифру 3?",{"0":[51.8,95.6,31.6,26.5],"1":[351.8,95.6,31.6,26.5],"2":[51.8,122.7,31.6,26.5],"3":[351.8,122.7,28.8,26.5],"4":[51.8,149.7,31.6,26.5]},"D","Куда вставить тройку?",[["Сохрани начало","Цифра 3 больше 2, 0 и 1, поэтому при вставке перед любой из этих цифр число станет больше, чем при вставке после них."],["Сравни два окончания","Цифра 3 меньше 4. Число 20134 меньше 20143, поэтому тройку лучше поставить между 1 и 4."]],""],[834,177,"Андрей написал правильный пример, а его младший брат заклеил бумажными кружочками все знаки действий. Получилось: 1 m 6 m 1 m 2 m 4 = 6. В каком порядке могли стоять знаки в этом примере?",{"0":[51.8,143.5,31.6,26.5],"1":[201.8,143.5,31.6,26.5],"2":[351.8,143.5,31.6,26.5],"3":[501.3,143.5,28.8,26.5],"4":[651.3,143.5,31.6,26.5]},"C","Знаки в примере",[["Сложи все числа","Если везде поставить плюс, получится 1 + 6 + 1 + 2 + 4 = 14."],["Измени последний знак","Когда +4 заменяем на −4, сумма уменьшается на 8. Получается 1 + 6 + 1 + 2 − 4 = 6."]],""],[842,135,"Паша бросает дротики в мишень, изображенную справа. Сколько очков он не мог набрать за два броска?",{"0":[51.8,100.9,31.6,26.5],"1":[161.8,100.9,31.6,26.5],"2":[278,100.9,31.6,26.5],"3":[394.7,100.9,28.8,26.5],"4":[511.4,100.9,31.6,26.5]},"C","Два броска",[["Посмотри на очки","За один бросок дают 30, 50 или 70 очков. Это 3, 5 или 7 десятков, то есть нечётное число десятков."],["Сложи десятки","Сумма двух нечётных чисел чётная. 90 — это 9 десятков, поэтому набрать 90 за два броска нельзя."]],""],[842,98,"Никита выписал числа от 1 до 31. На сколько больше он написал единиц, чем троек?",{"0":[51.8,64,31.6,26.5],"1":[201.8,64,31.6,26.5],"2":[351.8,64,31.6,26.5],"3":[501.3,64,28.8,26.5],"4":[651.3,64,31.6,26.5]},"B","Единицы и тройки",[["Посчитай единицы","В числах от 10 до 19 есть 10 единиц в разряде десятков. Ещё четыре единицы стоят в конце чисел 1, 11, 21 и 31. Всего 14."],["Посчитай тройки","Тройки стоят на конце чисел 3, 13 и 23, а ещё в начале чисел 30 и 31. Всего 5. Разница 14 − 5 = 9."]],""],[842,167,"Прямоугольник согнули пополам по жирной линии. Какая цифра оказалось не закрытой закрашенным квадратиком?",{"0":[51.8,93.9,31.6,26.5],"1":[201.8,93.9,31.6,26.5],"2":[351.8,93.9,31.6,26.5],"3":[51.8,125.5,28.8,26.5],"4":[201.8,125.5,31.6,26.5]},"C","Сгиб по линии",[["Отрази квадратики","При сгибе один столбец накладывается на тот же столбец. Самый близкий к сгибу нижний ряд накроет ближайший верхний ряд, следующий — следующий и так далее."],["Проверь цифру 6","Цифра 6 стоит во втором ряду над сгибом. В том же столбце второго ряда под сгибом клетка белая, поэтому цифра останется видна."]],""],[842,127,"Адам собрал меньше орехов, чем Мартин, но больше, чем Сьюзен. Дана собрала больше, чем Мартин, и меньше, чем Люси. Кто из них собрал больше всего орехов?",{"0":[51.8,93.3,31.6,26.5],"1":[201.8,93.3,31.6,26.5],"2":[351.8,93.3,31.6,26.5],"3":[501.3,93.3,28.8,26.5],"4":[651.3,93.3,31.6,26.5]},"A","Кто собрал больше орехов?",[["Построй цепочку","Сьюзен собрала меньше Адама, а Адам — меньше Мартина."],["Продолжи сравнение","Мартин собрал меньше Даны, а Дана — меньше Люси. Значит, больше всех собрала Люси."]],""],[842,125,"На планете Кенгуру один год состоит из 20 месяцев, а каждый месяц — из 6 недель. Четверть года у кенгурят каникулы. Сколько недель продолжаются каникулы?",{"0":[51.8,91.1,31.6,26.5],"1":[201.8,91.1,31.6,26.5],"2":[351.8,91.1,31.6,26.5],"3":[501.3,91.1,28.8,26.5],"4":[651.3,91.1,31.6,26.5]},"E","Каникулы на планете Кенгуру",[["Возьми четверть","Четверть от 20 месяцев — это 20 : 4 = 5 месяцев."],["Посчитай недели","В каждом месяце 6 недель, так что каникулы длятся 5 × 6 = 30 недель."]],""],[842,126,"Семеро детей сидят за круглым столом. Никакие два мальчика не сидят рядом, и никакие три девочки не сидят подряд. Сколько девочек за столом?",{"0":[51.8,91.7,31.6,26.5],"1":[201.8,91.7,31.6,26.5],"2":[351.8,91.7,31.6,26.5],"3":[501.3,91.7,28.8,26.5],"4":[651.3,91.7,31.6,26.5]},"C","Дети за круглым столом",[["Отдели мальчиков","Между соседними по кругу мальчиками должна сидеть хотя бы одна девочка. Поэтому мальчиков не больше трёх."],["Посмотри на промежутки","В каждом промежутке помещается максимум две девочки. Если мальчиков не больше двух, за столом всего не больше шести детей. Значит, мальчиков трое, а девочек четверо."]],""],[842,152,"Алиса заметила, что два месяца подряд 20-е число приходилось на четверг. Какой день недели будет 20-го числа в следующем за ними месяце?",{"0":[51.8,91.1,31.6,26.5],"1":[311.8,91.1,31.6,26.5],"2":[578,91.1,31.6,26.5],"3":[51.8,117.6,28.8,26.5],"4":[311.8,117.6,31.6,26.5]},"E","Три числа в календаре",[["Найди длину первого месяца","Между двумя четвергами прошло целое число недель. Среди обычных длин месяца только 28 дней делятся на 7, поэтому первым месяцем был февраль."],["Передвинься на три дня","За вторым 20-м числом идёт месяц длиной 31 день — март. Это четыре недели и три дня, поэтому 20 апреля будет в воскресенье."]],""],[842,100,"На рисунке справа AC = 12, BD = 15, CE = 11 и AB = DE. Чему равна длина CD?",{"0":[51.8,65.7,31.6,26.5],"1":[201.8,65.7,31.6,26.5],"2":[351.8,65.7,31.6,26.5],"3":[501.3,65.7,28.8,26.5],"4":[651.3,65.7,31.6,26.5]},"A","Отрезок CD",[["Сравни соседние части","AC на 1 длиннее CE, а AB и DE равны. Значит, если отнять эти равные отрезки, BC окажется на 1 длиннее CD."],["Раздели длину BD","BC и CD вместе дают 15. Если убрать лишнюю единицу из BC, две равные части дадут 14. Длина CD равна 7."]],""],[834,234,"Квадрат разрезан на четыре части, как показано на рисунке. Какую фигуру нельзя составить из этих частей?",{"0":[51.8,102.9,31.6,26.5],"1":[211.4,102.9,31.6,26.5],"2":[371.6,102.9,31.6,26.5],"3":[511.4,102.9,28.8,26.5],"4":[701,102.9,31.6,26.5]},"D","Четыре части квадрата",[["Найди детали","Получились прямоугольник 4 × 2, один большой треугольник и два маленьких треугольника."],["Проверь возможные фигуры","В А прямоугольник ложится поперёк середины, а большой треугольник даёт остриё снизу. В Б и Д положи прямоугольник вдоль нижнего края слева, а большой треугольник — на верхний выступ справа. В В прямоугольник ложится вдоль середины нижнего края, а большой треугольник — на верхний выступ слева."],["Посмотри на Г","В этих четырёх укладках остаются ровно два места для маленьких треугольников. В Г, если положить прямоугольник в среднюю полосу, остаются четыре отдельных маленьких треугольника. Подходит ответ Г."]],""],[834,155,"Вася взял в школу 18 конфет. Три конфеты он съел по дороге. Каждый раз, когда Вася съедал конфету в школе, он угощал конфетой Машу или Дашу, причем три раза он угостил сразу обеих девочек. Все конфеты были съедены. Сколько конфет съел Вася?",{"0":[51.8,120.4,31.6,26.5],"1":[201.8,120.4,31.6,26.5],"2":[351.8,120.4,31.6,26.5],"3":[501.3,120.4,28.8,26.5],"4":[651.3,120.4,31.6,26.5]},"C","Васины конфеты",[["Посчитай школьные конфеты","После дороги осталось 18 − 3 = 15 конфет. В школе на каждую Васину конфету пришлась одна конфета для девочки, а ещё в трёх случаях — вторая."],["Раздели на пары","Если отложить три дополнительные конфеты, останется 12 конфет в парах. В школе Вася съел 6, по дороге — 3, всего 9."]],""],[834,155,"В ребусе одинаковые буквы обозначают одинаковые цифры, а разные буквы — разные цифры. Известно, что цифры 0, 8 и 9 не использованы. Какая еще цифра не использована?",{"0":[51.8,121,31.6,26.5],"1":[178.1,121,31.6,26.5],"2":[311.8,121,31.6,26.5],"3":[444.9,121,28.8,26.5],"4":[578,121,31.6,26.5]},"B","Буквенный ребус",[["Начни с сотен","При сложении двух двузначных чисел сотня может быть только 1. Значит, У = 1. Тогда Е + Г = 11 и переносит одну десятку."],["Проверь пары","Из цифр 2–7 сумма 11 получается только у пар 4 и 7 или 5 и 6. Среди оставшихся цифр наибольшая сумма К + Н тоже 11. А чтобы в ответе вышло 1Р1, нужна сумма К + Н + 1 хотя бы 12, так как Р уже не может быть 0 или 1."],["Найди лишнюю цифру","В обоих случаях используются пары 4 и 7, 5 и 6, а Р = 2. Из цифр 1–7 не понадобилась 3."]],""],[834,155,"Летом дети ездили на велосипедах с дачи на озеро. От дачи до озера 3 км. Игорь проезжал весь путь за 10 минут, Маша ехала в 2 раза дольше, а Аня ехала быстрее Маши, но медленнее Игоря. Какая скорость могла быть у Ани?",{"0":[51.8,121,31.6,26.5],"1":[201.8,121,31.6,26.5],"2":[351.8,121,31.6,26.5],"3":[501.3,121,28.8,26.5],"4":[651.3,121,31.6,26.5]},"C","Скорость до озера",[["Найди две скорости","За час Игорь проехал бы 6 отрезков по 3 км, то есть 18 км. Маша ехала вдвое дольше, поэтому её скорость 9 км/ч."],["Выбери между ними","Скорость Ани больше 9 и меньше 18 км/ч. Из предложенных подходит 12 км/ч."]],""],[834,220,"После того, как в 7 : 00 прозвенел будильник, Вася стукнул по нему кулаком, и минутная стрелка стала двигаться в 12 раз быстрее, чем надо. Что покажет этот будильник в 7 : 55?",{"0":[51.8,186.4,31.6,26.5],"1":[201.8,186.4,31,26.5],"2":[351.8,186.4,31.6,26.5],"3":[501.3,186.4,28.2,26.5],"4":[644.6,186.4,31.6,26.5]},"E","Сломанный будильник",[["Проверь минутную стрелку","За 55 минут она проходит 55 × 12 = 660 минутных делений, то есть ровно 11 кругов. Стрелка снова у цифры 12."],["Посмотри на часовую","Обычная часовая стрелка показывает почти 8, ведь наступило 7:55. Обе стрелки так стоят на рисунке Д."]],""],[834,155,"У малыша Феди есть 10 красных кубиков, 15 синих и 30 зеленых. Он хочет построить из них башню так, чтобы любые два соседних кубика имели разный цвет. Сколько кубиков будет в самой высокой башне, которую сможет построить Федя?",{},"D","Башня из кубиков",[["Сделай разделители","Красных и синих кубиков вместе 25. Если выложить их в ряд, между ними 24 места, и ещё два места есть по краям."],["Заполни зелёными","Поставь по одному зелёному кубику в каждое из 26 мест. Больше 26 нельзя, иначе зелёные окажутся рядом. Всего получится 51 кубик."]],""],[842,130,"Братец Кролик за день съедает или 9 морковок, или 2 кочана капусты, или 1 кочан капусты и 4 морковки. За неделю он съел 30 морковок. Сколько кочанов капусты он съел за эту неделю?",{"0":[51.8,96.2,31.6,26.5],"1":[161.8,96.2,31.6,26.5],"2":[278,96.2,31.6,26.5],"3":[394.7,96.2,28.8,26.5],"4":[501.3,96.2,31.6,26.5]},"B","Меню Братца Кролика",[["Посчитай морковные дни","Пробуем брать по 9 морковок ноль, один, два или три дня. Только после двух таких дней остаток 30 − 18 = 12 делится на 4. Это ещё три дня по 4 морковки."],["Посчитай капусту","За смешанные дни съедено 3 кочана. Оставшиеся два дня были только капустными: ещё 4 кочана. Всего 7."]],""],[842,171,"Какое наименьшее число клеток надо закрасить, чтобы в любом квадратике 2 × 2 на рисунке была хотя бы одна закрашенная клетка?",{"0":[51.8,136.3,31.6,26.5],"1":[161.8,136.3,31.6,26.5],"2":[278,136.3,31.6,26.5],"3":[394.7,136.3,28.8,26.5],"4":[501.3,136.3,31.6,26.5]},"D","Клетки для закраски",[["Найди нижнюю границу","На рисунке можно выделить четыре квадрата 2 × 2 вокруг центра так, чтобы они не пересекались. Они идут по кругу: сверху, справа, снизу и слева. В каждом надо закрасить хотя бы одну клетку."],["Закрась четыре клетки","Возьми четыре клетки, которые касаются центральной уголками. В каждом квадрате 2 × 2 найдётся одна из них. Значит, четырёх хватает."]],""],[842,210,"Фрекен Бок поставила на стол 15 тарелок с булочками. На первой тарелке лежит одна булочка, на второй — две, на третьей — три, и так далее. Иногда в окно влетает Карлсон, выбирает несколько тарелок и съедает с каждой из них одинаковое количество булочек. За какое наименьшее число визитов Карлсон сможет съесть все булочки?",{"0":[51.8,176.8,31.6,26.5],"1":[161.8,176.8,31.6,26.5],"2":[278,176.8,31.6,26.5],"3":[394.7,176.8,28.8,26.5],"4":[501.3,176.8,31.6,26.5]},"B","Визиты Карлсона",[["Проверь, хватит ли трёх","За три визита каждую тарелку можно выбрать или пропустить три раза. Получится только 7 непустых наборов визитов, то есть максимум 7 разных количеств булочек."],["Разложи числа на суммы","За четыре визита Карлсон может съедать с выбранных тарелок по 1, 2, 4 или 8 булочек. Из этих чисел можно сложить любое число от 1 до 15, например 13 = 8 + 4 + 1. Значит, четырёх визитов хватает."]],""],[842,169,"Какой кубик получится из данной развертки?",{"0":[51.8,132.2,31.6,26.5],"1":[174.7,132.2,31.6,26.5],"2":[294.9,132.2,31.6,26.5],"3":[411.6,132.2,28.8,26.5],"4":[521.6,132.2,31.6,26.5]},"E","Кубик со стрелками",[["Сложи пояс","Четыре клетки в одной строке станут поясом кубика. Стрелка на первой клетке направлена ко второй. Стрелка на отдельной нижней грани направлена к четвёртой клетке пояса."],["Сравни направления","Вторая и четвёртая грани пояса противоположны. Поэтому стрелки смотрят в противоположные стороны. Если повернуть кубик, как в вариантах, правильная картинка — Д."]],""],[842,129,"Назовем трехзначное число удивительным, если оно делится на 3, а первая и последняя цифры у него одинаковы. Чему равна наименьшая разность между двумя удивительными числами?",{"0":[51.8,95.6,31.6,26.5],"1":[201.8,95.6,31.6,26.5],"2":[351.8,95.6,31.6,26.5],"3":[501.3,95.6,28.8,26.5],"4":[651.3,95.6,31.6,26.5]},"C","Удивительные числа",[["Сравни соседние записи","Если первая цифра у обоих чисел одна и та же, разность — число десятков, кратное 3, то есть хотя бы 30. Если первые цифры различны, самая маленькая возможная разность получается на границе сотен и равна хотя бы 11."],["Проверь разность","На границе соседних сотен разность кончается на 1. Число 11 не делится на 3, а 21 делится. Пара 282 и 303 даёт ровно 21."]],""],[842,207,"На рисунке изображен план дома Кенги. Любые две соседние комнаты соединены дверью. Кенга хочет пройти из комнаты А в комнату В, не проходя ни через какую комнату более одного раза. Сколькими способами Кенга сможет это сделать?",{"0":[51.8,172.9,31.6,26.5],"1":[161.8,172.9,31.6,26.5],"2":[278,172.9,31.6,26.5],"3":[394.7,172.9,28.8,26.5],"4":[501.3,172.9,31.6,26.5]},"D","Дороги в доме Кенги",[["Найди общую комнату","Два квадрата по 3 × 3 комнаты соединяются через одну общую угловую комнату. Сначала посчитай пути из угла в противоположный угол в одном квадрате."],["Разбей пути по длине","Без повторов можно пройти за 4, 6 или 8 переходов. Если первый шаг вправо, остаются 3 кратчайших пути, 2 пути с одним обходом и 1 путь змейкой. С первым шагом вниз столько же. Всего 12."],["Соедини пути","Для каждого из 12 путей к общей комнате можно выбрать любой из 12 путей от неё к выходу. Получается 12 × 12 = 144."]],""]]]];
globalThis.KENGURU_LEGACY_CONDITIONS = {"2014":{"1":{"question":"Боря выложил из одинаковых палочек слово КЕНГУРУ. Сколько букв сложены из 5 палочек?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2014/task-01.svg","imageWidth":444,"imageHeight":105},"2":{"question":"Как в математике называется число, которое вычитают?","choices":["вычтенное","вычитуемое","вычитываемое","вычитающееся","вычитаемое"]},"3":{"question":"Как выглядит центральная часть звезды, изображенной на рисунке справа?","image":"assets/legacy-conditions/2014/task-03.webp","imageWidth":946,"imageHeight":296},"4":{"question":"Во сколько раз 10 метров больше 1 мм?","choices":["100 000","10 000","1000","100","10"]},"5":{"question":"Аня хочет вставить цифру 3 в число 2014 так, чтобы получившееся пятизначное число было как можно меньше. Где она должна написать цифру 3?","choices":["перед цифрой 2","между цифрами 2 и 0","между цифрами 0 и 1","между цифрами 1 и 4","после цифры 4"]},"6":{"question":"Андрей написал правильный пример, а его младший брат заклеил бумажными кружочками все знаки действий. Получилось 1 ○ 6 ○ 1 ○ 2 ○ 4 = 6. В каком порядке могли стоять знаки в этом примере?","choices":["+ + − +","+ − − +","+ + + −","+ − + −","+ − − −"]},"7":{"question":"Паша бросает дротики в мишень, изображенную справа. Сколько очков он не мог набрать за два броска?","choices":["60","80","90","100","120"],"image":"assets/legacy-conditions/2014/task-07.svg","imageWidth":220,"imageHeight":216},"8":{"question":"Никита выписал числа от 1 до 31. На сколько больше он написал единиц, чем троек?","choices":["8","9","10","11","13"]},"9":{"question":"Прямоугольник согнули пополам по жирной линии. Какая цифра оказалась не закрытой закрашенным квадратиком?","choices":["1","3","6","7","8"],"image":"assets/legacy-conditions/2014/manual-09.webp","imageWidth":207,"imageHeight":164},"10":{"question":"Адам собрал меньше орехов, чем Мартин, но больше, чем Сьюзен. Дана собрала больше, чем Мартин, и меньше, чем Люси. Кто из них собрал больше всего орехов?","choices":["Люси","Мартин","Сьюзен","Дана","Адам"]},"11":{"question":"На планете Кенгуру один год состоит из 20 месяцев, а каждый месяц — из 6 недель. Четверть года у кенгурят каникулы. Сколько недель продолжаются каникулы?","choices":["5","6","10","24","30"]},"12":{"question":"Семеро детей сидят за круглым столом. Никакие два мальчика не сидят рядом, и никакие три девочки не сидят подряд. Сколько девочек за столом?","choices":["2","3","4","5","6"]},"13":{"question":"Алиса заметила, что два месяца подряд 20-е число приходилось на четверг. Какой день недели будет 20-го числа в следующем за ними месяце?","choices":["понедельник","вторник","среда","пятница","воскресенье"]},"14":{"question":"На рисунке справа AC = 12, BD = 15, CE = 11 и AB = DE. Чему равна длина CD?","choices":["7","8","10","11","23"],"image":"assets/legacy-conditions/2014/task-14.webp","imageWidth":272,"imageHeight":48},"15":{"question":"Квадрат разрезан на четыре части, как показано на рисунке. Какую фигуру нельзя составить из этих частей?","image":"assets/legacy-conditions/2014/task-15.webp","imageWidth":950,"imageHeight":297},"16":{"question":"Вася взял в школу 18 конфет. Три конфеты он съел по дороге. Каждый раз, когда Вася съедал конфету в школе, он угощал конфетой Машу или Дашу, причем три раза он угостил сразу обеих девочек. Все конфеты были съедены. Сколько конфет съел Вася?","choices":["7","8","9","10","11"]},"17":{"question":"В ребусе одинаковые буквы обозначают одинаковые цифры, а разные буквы — разные цифры. Известно, что цифры 0, 8 и 9 не использованы. Какая еще цифра не использована?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2014/task-17.svg","imageWidth":174,"imageHeight":220},"18":{"question":"Летом дети ездили на велосипедах с дачи на озеро. От дачи до озера 3 км. Игорь проезжал весь путь за 10 минут, Маша ехала в 2 раза дольше, а Аня ехала быстрее Маши, но медленнее Игоря. Какая скорость могла быть у Ани?","choices":["20 км/ч","18 км/ч","12 км/ч","9 км/ч","6 км/ч"]},"19":{"question":"После того, как в 7:00 прозвенел будильник, Вася стукнул по нему кулаком, и минутная стрелка стала двигаться в 12 раз быстрее, чем надо. Что покажет этот будильник в 7:55?","image":"assets/legacy-conditions/2014/task-19.webp","imageWidth":939,"imageHeight":155},"20":{"question":"У малыша Феди есть 10 красных кубиков, 15 синих и 30 зеленых. Он хочет построить из них башню так, чтобы любые два соседних кубика имели разный цвет. Сколько кубиков будет в самой высокой башне, которую сможет построить Федя?","choices":["30","32","50","51","55"]},"21":{"question":"Братец Кролик за день съедает или 9 морковок, или 2 кочана капусты, или 1 кочан капусты и 4 морковки. За неделю он съел 30 морковок. Сколько кочанов капусты он съел за эту неделю?","choices":["6","7","8","9","10"]},"22":{"question":"Какое наименьшее число клеток надо закрасить, чтобы в любом квадратике 2 × 2 на рисунке была хотя бы одна закрашенная клетка?","choices":["8","6","5","4","3"],"image":"assets/legacy-conditions/2014/task-22.svg","imageWidth":220,"imageHeight":220},"23":{"question":"Фрекен Бок поставила на стол 15 тарелок с булочками. На первой тарелке лежит одна булочка, на второй — две, на третьей — три, и так далее. Иногда в окно влетает Карлсон, выбирает несколько тарелок и съедает с каждой из них одинаковое количество булочек. За какое наименьшее число визитов Карлсон сможет съесть все булочки?","choices":["3","4","5","10","15"]},"24":{"question":"Какой кубик получится из данной развертки?","image":"assets/legacy-conditions/2014/task-24.webp","imageWidth":947,"imageHeight":212},"25":{"question":"Назовем трехзначное число удивительным, если оно делится на 3, а первая и последняя цифры у него одинаковы. Чему равна наименьшая разность между двумя удивительными числами?","choices":["12","15","21","30","51"]},"26":{"question":"На рисунке изображен план дома Кенги. Любые две соседние комнаты соединены дверью. Кенга хочет пройти из комнаты А в комнату В, не проходя ни через какую комнату более одного раза. Сколькими способами Кенга сможет это сделать?","choices":["24","36","81","144","288"],"image":"assets/legacy-conditions/2014/task-26.webp","imageWidth":242,"imageHeight":240}}};
'use strict';

(() => {
  const latin = ['A', 'B', 'C', 'D', 'E'];
  const cyrillic = ['А', 'Б', 'В', 'Г', 'Д'];
  const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;');
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const source = 'assets/kenguru';
  const ink = '#173439';
  const teal = '#237e79';
  const mint = '#e5f2ea';
  const muted = '#e8eee8';
  const line = '#b3c6bf';
  const gold = '#f7dda8';

  const text = (x, y, value, size = 27, color = ink, anchor = 'middle') =>
    `<text x="${x}" y="${y}" fill="${color}" font-family="system-ui, sans-serif" font-weight="700" font-size="${size}" text-anchor="${anchor}" dominant-baseline="middle">${escape(value)}</text>`;
  const box = (x, y, w, h, fill, stroke = 'none', radius = 10) =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}"/>`;
  const segment = (x1, y1, x2, y2, color, width = 3) =>
    `<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`;
  const dot = (x, y, radius, fill) => `<circle cx="${x}" cy="${y}" r="${radius}" fill="${fill}"/>`;
  const svg = (width, height, label, inside, className = 'legacy-scene') =>
    `<svg class="${className}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(label)}">${inside}</svg>`;
  const image = (url, width, height) => `<image href="${url}" width="${width}" height="${height}"/>`;
  const progress = (frame, end) => Math.max(0, Math.min(1, frame / end));

  function renderOriginal(url, width, height, label, mark, frame) {
    let focus = '';
    if (mark) {
      const [x, y, w, h] = mark;
      const dash = .68 + .32 * progress(frame, 8);
      focus = `<rect x="${x - 4}" y="${y - 2}" width="${w + 8}" height="${h + 4}" rx="4" fill="none" stroke="${teal}" stroke-width="4" pathLength="1" stroke-dasharray="${dash} 1"/>`;
    }
    return svg(width, height, label, image(url, width, height) + focus);
  }

  function crop(url, width, height, [sx, sy, sw, sh], x, y, w, h) {
    return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" style="overflow:hidden">${image(url, width, height)}</svg>`;
  }

  function workedScene([height, drawing], label, answer) {
    const size = 720;
    const band = answer ? 51 : 0;
    const badge = answer
      ? box(16, height, size - 32, 42, mint, line) + text(size / 2, height + 21, `Ответ ${answer}`, 24, teal)
      : '';
    return svg(size, height + band, label, drawing + badge, 'legacy-scene legacy-worked-scene');
  }

  // Extract only equations that the author explicitly uses in this step. A
  // space can group thousands, so it must not split their numeric tokens.
  const number = String.raw`[−-]?\d+(?:[ \u00a0\u202f]\d{3}(?!\d))*(?:[.,]\d+)?`;
  const operator = String.raw`[+−–×·⋅*÷:/=<>≤≥-]`;
  const equation = new RegExp(String.raw`${number}(?:\s*${operator}\s*${number})+`, 'gu');
  const tokens = new RegExp(String.raw`^(${number})|(${operator})\s*(${number})`, 'gu');

  function equationsIn(message) {
    return [...message.matchAll(equation)].map(match => match[0])
      .filter(value => /[=<>≤≥]/u.test(value))
      .map(value => [...value.matchAll(tokens)].flatMap(([, first, sign, next]) => first ? [first] : [sign, next]));
  }

  function drawEquations(rows, frame) {
    const drawing = rows.map((parts, row) => {
      const current = Math.min(parts.length - 1, Math.floor(Math.max(0, frame - row * 4) / 2));
      const sizes = parts.map((part, i) => i % 2 ? 32 : Math.max(48, 23 + part.length * 17));
      const width = sizes.reduce((sum, w) => sum + w, 0);
      const factor = Math.min(640 / width, 1);
      let x = (720 - width * factor) / 2;
      const y = 15 + row * 75;
      return box(16, y, 688, 62, '#f6f8f3') + parts.map((part, i) => {
        const w = sizes[i] * factor;
        const highlight = current === i;
        const result = i === parts.length - 1;
        const plate = (i % 2 === 0 || highlight)
          ? box(x + 2, y + 7, w - 4, 48, highlight ? gold : result ? mint : '#fff', result ? teal : 'none') : '';
        const item = plate + text(x + w / 2, y + 31, part, 32 * factor, result ? teal : ink);
        x += w;
        return item;
      }).join('');
    }).join('');
    return [rows.length * 75 + 13, drawing];
  }

  // The checked statement and the worksheet choices are transcribed together.
  // For illustrated choices, the approach below uses the original artwork.
  const authored = {
    '2001/3': {
      question: 'У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?',
      choices: ['5', '6', '7', '8', '9'],
      draw: drawSticks,
    },
    '2002/2': {
      question: 'Чему равно число 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2?',
      choices: ['0', '2', '4', '12', '20'],
      draw: drawPairs,
    },
    '2003/3': {
      question: 'На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?',
      crop: [73, 65, 662, 131],
      illustration: 'Пять рисунков с сердечками, ромбами и треугольниками, варианты от A до E',
      draw: drawHearts,
    },
    '2004/4': {
      question: 'Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?',
      choices: ['5', '7', '9', '11', '12'],
      draw: drawStairs,
    },
    '2005/3': {
      illustration: 'Квадратная таблица с восемью кенгуру',
      draw: drawKangaroos,
    },
    '2006/10': {
      question: 'Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?',
      choices: ['3', '4', '5', '6', '7'],
      draw: drawNumberLine,
    },
    '2007/1': {
      question: 'Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?',
      choices: ['1', '2', '3', '4', '5'],
      draw: drawLetters,
    },
    '2008/6': {
      question: 'В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?',
      choices: ['12', '8', '6', '4', '2'],
      draw: drawAquariums,
    },
    '2009/2': {
      question: '200 × 9 + 200 + 9 = ?',
      choices: ['418', '1909', '2009', '4018', '20009'],
    },
    '2010/2': {
      question: 'Дети измерили шагами длину дорожки. У Ани получилось 17 шагов, у Наташи 15, у Дениса 14, у Вани 13 и у Тани 12. Кто из этих детей имеет самый длинный шаг?',
      choices: ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'],
      draw: (step, frame) => drawBars(
        ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'], [17, 15, 14, 13, 12], step === 2 ? 4 : -1, frame),
    },
    '2011/3': {
      question: 'Через три с половиной часа отправляется поезд, на котором Сёма поедет к бабушке. Боясь проспать, он проснулся полтора часа назад. За сколько часов до отправления поезда Сёма проснулся?',
      choices: ['за полтора часа', 'за 2 часа', 'за 3 с половиной часа', 'за 4 часа', 'за 5 часов'],
      draw: (step, frame) => drawTimeline(
        ['Пробуждение', 'Сейчас', 'Отправление'], [1.5, 3.5], ['1,5 ч', '3,5 ч'], step === 2 ? '5 часов' : '', frame),
    },
    '2012/4': {
      question: 'Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?',
      choices: ['4 руб.', '6 руб.', '8 руб.', '10 руб.', '12 руб.'],
      draw: drawBalloons,
    },
    '2013/4': {
      question: 'Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?',
      choices: ['3 дм 2 см', '3 см 7 мм', '35 мм', '3 см', '302 мм'],
      draw: (step, frame) => step === 1
        ? drawEquations(equationsIn('300 + 20 = 320'), frame)
        : drawBars(['А', 'Б', 'В', 'Г', 'Д'], [320, 37, 35, 30, 302], 0, frame, ' мм'),
    },
    '2014/1': {
      illustration: 'Буквы слова КЕНГУРУ, сложенные из палочек',
      draw: drawStickLetters,
    },
    '2015/2': {
      question: 'Чему равна сумма двадцати сотен и пятнадцати?',
      choices: ['35', '215', '2015', '20015', '200015'],
    },
    '2016/2': {
      question: 'Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?',
      choices: ['21 марта', '24 марта', '26 марта', '28 марта', '30 марта'],
      draw: (step, frame) => drawTimeline(
        ['17 марта', step === 2 ? '21 марта' : '8 недель', step === 2 ? '28 марта' : '9 недель'],
        [4, 7], ['4 дня', '7 дней'], step === 2 ? '11 дней' : '', frame),
    },
    '2017/1': {
      question: 'Кенга составила пять примеров на сложение. Какая сумма самая большая?',
      choices: ['2 + 0 + 1 + 7', '2 + 0 + 17', '20 + 17', '20 + 1 + 7', '201 + 7'],
      draw: drawSums,
    },
    '2018/3': {
      question: 'В Петербурге 15 марта в 16 часов пошел снег, а 16 марта в 15 часов снегопад закончился. Сколько часов он продолжался?',
      choices: ['11', '12', '23', '24', '25'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['15 марта, 16:00', 'Полночь'] : ['15 марта, 16:00', 'Полночь', '16 марта, 15:00'],
        step === 1 ? [8] : [8, 15], step === 1 ? ['8 ч'] : ['8 ч', '15 ч'], step === 2 ? '23 часа' : '', frame, 23),
    },
    '2019/1': {
      question: 'В зоопарке 21 ноября 2018 года родился кенгуренок. Сколько месяцев ему исполнилось 21 марта 2019 года?',
      choices: ['3', '4', '5', '6', '7'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['21 нояб.', '21 дек.', '21 янв.'] : ['21 нояб.', '21 дек.', '21 янв.', '21 февр.', '21 марта'],
        step === 1 ? [1, 1] : [1, 1, 1, 1], step === 1 ? ['1 мес.', '1 мес.'] : ['1 мес.', '1 мес.', '1 мес.', '1 мес.'],
        step === 2 ? '4 месяца' : '', frame, 4),
    },
  };

  function drawSticks(step, frame) {
    let drawing = '';
    for (let i = 0; i < 6; i++) drawing += segment(101 + i * 70, 38, 101 + i * 70, 117, teal, 11);
    drawing += text(275, 150, '6 целых', 26);
    const gap = step === 1 ? 0 : 20 + 9 * progress(frame, 8);
    drawing += segment(567 - gap, 38, 567 - gap, 74, '#bc6340', 11);
    drawing += segment(567 + gap, 82, 567 + gap, 117, '#bc6340', 11);
    drawing += text(567, 150, step === 1 ? 'сломанная' : '2 половины', 26);
    return [180, drawing];
  }

  function drawPairs(step, frame) {
    let drawing = box(17, 22, 119, 61, mint) + text(77, 52, '2 + 2', 30);
    const active = Math.min(3, Math.floor(Math.max(0, frame) / 4));
    for (let i = 0; i < 4; i++) {
      const x = 151 + 139 * i;
      drawing += box(x, 22, 130, 61, step === 1 && i === active ? gold : muted);
      drawing += text(x + 65, 52, step === 1 ? '−2 + 2' : '0', 30);
      if (step === 1) drawing += segment(x + 65, 89, x + 65, 111, teal) + text(x + 65, 137, '0', 26, teal);
    }
    if (step === 2) drawing += text(360, 137, '2 + 2 = 4', 33, teal);
    return [173, drawing];
  }

  function drawHearts(step, frame, card) {
    if (step === 1) {
      let drawing = '';
      for (let i = 0; i < 4; i++) {
        const x = 105 + i * 128;
        drawing += box(x, 40, 105, 81, i === 3 ? muted : mint, line);
        drawing += text(x + 52, 80, i === 3 ? '◇' : '♥', 49, i === 3 ? ink : '#a34849');
      }
      return [175, drawing + text(360, 145, '3 из 4', 30, teal)];
    }
    const [url, w, h] = card;
    const choiceImage = globalThis.KENGURU_CHOICE_LAYOUTS?.['2003-3-4/3']?.options[3]?.image;
    const drawing = choiceImage
      ? `<image href="${escape(choiceImage)}" x="251" y="11" width="228" height="240"/>`
      : crop(url, w, h, [493, 66, 76, 80], 251, 11, 228, 240);
    const alpha = .45 + progress(frame, 9) * .55;
    return [260, drawing +
      `<g opacity="${alpha}">` +
      box(256, 15, 216, 158, 'none', '#a34849') + box(256, 176, 216, 73, 'none', teal) +
      text(490, 94, '9 сердец', 27, '#a34849', 'start') +
      text(490, 206, '3 другие фигуры', 23, teal, 'start') + '</g>'];
  }

  function drawStairs(step, frame) {
    let drawing = '';
    for (let i = 1; i <= 11; i++) {
      const x = 26 + 60 * (i - 1);
      const y = 176 - 13 * (i - 1);
      const landed = i % 2 === 0;
      const active = landed && i / 2 === Math.min(5, 1 + Math.floor(Math.max(frame, 0) / 4));
      const remaining = i === 11 && step === 2;
      drawing += box(x, y, 59, 36, active ? gold : remaining || landed ? mint : muted, line, 4);
      if (i < 11 || remaining) drawing += text(x + 30, y + 18, i, 24, landed || remaining ? teal : ink);
      if (landed) drawing += dot(x + 30, y - 15, active ? 8 : 5, teal);
      if (remaining) drawing += text(x + 30, y - 20, '+1', 22, teal);
    }
    return [225, drawing];
  }

  function drawKangaroos(step, frame, figure) {
    const [url, w, h] = figure;
    const locations = [[0, 0], [0, 1], [1, 0], [1, 3], [2, 2], [2, 3], [3, 2], [1, 2]];
    let drawing = '';
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        const fill = step === 1 && (row === 1 || col === 2) ? gold
          : row === 3 && col === 1 ? mint : '#fff';
        drawing += box(204 + col * 64, 14 + row * 64, 64, 64, fill, line, 0);
      }
    }
    const moving = step === 2 ? (frame === 0 ? 1 : progress(frame, 10)) : 0;
    if (step === 2 && frame > 0) {
      drawing += `<path d="M364 110 Q230 144 300 238" fill="none" stroke="${teal}" stroke-width="3" stroke-dasharray="7 5"/>`;
    }
    locations.forEach(([row, col], i) => {
      const active = i === locations.length - 1;
      const shift = active ? moving : 0;
      const x = 210 + col * 64 - shift * 64;
      const y = 21 + row * 64 + shift * 128 - 37 * Math.sin(shift * Math.PI);
      if (active) drawing += box(x - 3, y - 3, 58, 57, mint, teal, 7);
      drawing += `<svg x="${x}" y="${y}" width="52" height="50" viewBox="16 21 65 62" style="overflow:hidden;mix-blend-mode:multiply">${image(url, w, h)}</svg>`;
    });
    const counts = moving === 1 ? [2, 2, 2, 2] : moving === 0 ? [2, 3, 2, 1] : [2, 2, 2, 1];
    for (let i = 0; i < 4; i++) {
      drawing += text(489, 46 + i * 64, counts[i], 24, teal);
      drawing += text(236 + i * 64, 296, i === 1 ? counts[3] : i === 2 ? counts[1] : 2, 24, teal);
    }
    return [321, drawing];
  }

  function drawNumberLine(step, frame) {
    let drawing = segment(44, 99, 676, 99, line, 4);
    for (let i = 0; i < 10; i++) {
      const x = 45 + i * 70;
      const marked = i === 4 || (step === 2 && i > 4);
      const active = i === 4 + Math.min(step === 1 ? 0 : 5, Math.floor(Math.max(0, frame) / 3));
      if (marked) drawing += box(x - 28, 53, 56, 44, active ? gold : mint);
      drawing += text(x, 75, 96 + i, 23, marked ? teal : ink) + dot(x, 99, marked ? 6 : 4, marked ? teal : line);
      if (marked) drawing += text(x, 126, '+' + i, 20, teal);
    }
    return [155, drawing];
  }

  function drawLetters(step, frame) {
    const words = ['КЕНГУРУ', 'МАТЕМАТИКА'];
    const active = Math.min(words[0].length - 1, Math.floor(Math.max(0, frame) / 3));
    return [166, words.map((word, row) => [...word].map((letter, i) => {
      const x = 360 - word.length * 32 + i * 64;
      const y = 19 + row * 67;
      const common = step === 2 && 'КЕ'.includes(letter);
      const comparable = step === 1 && (row === 0 ? i === active : letter === words[0][active]);
      return box(x, y, 56, 54, common ? mint : comparable ? gold : muted, common ? teal : line) +
        text(x + 28, y + 27, letter, 30, common ? teal : ink);
    }).join('')).join('')];
  }

  function drawAquariums(step, frame) {
    const moved = step === 1 ? 1 : 6;
    const now = frame === 0 ? moved : Math.min(moved, 1 + Math.floor(frame / 3));
    let drawing = '';
    for (let tank = 0; tank < 2; tank++) {
      const x = 21 + tank * 365;
      drawing += box(x, 18, 313, 128, mint, line);
      drawing += text(x + 156, 40, tank ? 'Второй аквариум' : 'Первый аквариум', 22);
      drawing += text(x + 40, 96, '□ +', 25, teal);
      for (let i = 0; i < (tank ? now : 12 - now); i++) {
        drawing += dot(x + 81 + (i % 6) * 36, 81 + Math.floor(i / 6) * 33, 11, tank ? '#bc6340' : teal);
      }
    }
    drawing += text(360, 82, '→', 27, ink);
    const difference = now === 6 ? '6 = 6' : `${12 - now} − ${now} = ${12 - 2 * now}`;
    drawing += text(360, 174, difference, 29, teal);
    return [197, drawing];
  }

  function drawBars(names, values, highlighted, frame, unit = '') {
    const max = Math.max(...values);
    const active = Math.min(values.length - 1, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < values.length; i++) {
      const y = 12 + i * 46;
      const w = values[i] / max * 450;
      drawing += text(124, y + 17, names[i], 22, ink, 'end');
      drawing += box(146, y, w, 34, i === highlighted ? teal : i === active ? gold : muted, line, 7);
      drawing += text(156 + w, y + 17, values[i] + unit, 22, i === highlighted ? teal : ink, 'start');
    }
    return [values.length * 46 + 6, drawing];
  }

  function drawTimeline(labels, sizes, durations, total, frame, span = sizes.reduce((sum, size) => sum + size, 0)) {
    const active = Math.min(sizes.length - 1, Math.floor(Math.max(0, frame) / 6));
    let x = 103;
    let drawing = '';
    sizes.forEach((size, i) => {
      const end = x + 514 * size / span;
      drawing += segment(x, 65, end, 65, i === active ? '#c07848' : teal, 8);
      drawing += dot(x, 65, 8, teal);
      drawing += text(x, 100, labels[i], 21);
      drawing += text((x + end) / 2, 34, durations[i], 25, teal);
      x = end;
    });
    drawing += dot(x, 65, 8, teal) + text(x, 100, labels.at(-1), 21);
    if (total) drawing += box(103, 129, 514, 40, mint) + text(360, 149, total, 26, teal);
    return [total ? 183 : 128, drawing];
  }

  function drawBalloons(step, frame) {
    const active = Math.min(2, 1 + Math.floor(Math.max(0, frame) / 4));
    let drawing = segment(343, 62, 586, 62, teal, 3) + text(464, 36, '12 руб.', 26, teal);
    for (let i = 0; i < 3; i++) {
      const x = 175 + i * 144;
      const color = i === 0 ? '#a9b9b2' : i === active ? '#bc6340' : teal;
      drawing += dot(x, 118, 38, color);
      drawing += box(x - 6, 151, 12, 12, color, 'none', 0);
      drawing += segment(x, 162, x, 181, color);
      drawing += text(x, 207, i === 0 ? 'вычитаем' : step === 1 ? '?' : '6 руб.', 25, color);
      if (i === 0) drawing += segment(x - 45, 165, x + 45, 77, '#7d4940', 4);
    }
    return [239, drawing];
  }

  function drawStickLetters(step, frame, figure) {
    const [url, w, h] = figure;
    const sources = [[7, 43], [57, 57], [123, 60], [193, 56], [253, 53], [313, 62], [380, 58]];
    const values = [4, 5, 5, 3, 3, 5, 3];
    const active = Math.min(6, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < sources.length; i++) {
      const [sx, sw] = sources[i];
      const x = 24 + i * 98;
      const relevant = step === 2 ? values[i] === 5 : values[i] !== 5;
      drawing += box(x, 21, 85, 126, relevant ? mint : muted, relevant ? teal : line);
      const letterWidth = sw * 77 / 100;
      drawing += crop(url, w, h, [sx, 3, sw, 100], x + (85 - letterWidth) / 2, 30, letterWidth, 77);
      if (relevant) drawing += text(x + 43, 125, values[i], 24, active === i ? '#a24d36' : teal);
    }
    return [167, drawing];
  }

  function drawSums(step, frame) {
    if (step === 2) return drawBars(['А', 'Б', 'В', 'Г', 'Д'], [10, 19, 37, 28, 208], 4, frame);
    const expressions = authored['2017/1'].choices;
    const drawing = expressions.map((value, i) => {
      const x = 12 + i * 140;
      return box(x, 25, 135, 61, i === 4 ? mint : muted, i === 4 ? teal : line) +
        text(x + 67, 55, value, 22, i === 4 ? teal : ink);
    }).join('');
    return [113, drawing];
  }

  for (const [year, label, tasks] of globalThis.KENGURU_LEGACY ?? []) {
    const letters = year < 2008 ? latin : cyrillic;
    const lessons = [];
    const scenes = [];
    for (const [i, [width, height, , marks, key, name, explanation, note]] of tasks.entries()) {
      const number = i + 1;
      const answer = key === '?' ? null : latin.indexOf(key);
      const originalImage = `assets/years/${year}/task-${String(number).padStart(2, '0')}.webp`;
      const card = [originalImage, width, height];
      const authoredTask = authored[year + '/' + number];
      const imported = globalThis.KENGURU_LEGACY_CONDITIONS?.[year]?.[number];
      const native = authoredTask?.question ? authoredTask : imported ?? authoredTask;
      const figure = native === imported && imported?.image
        ? [imported.image, imported.imageWidth, imported.imageHeight] : null;
      const illustration = figure
        ? svg(imported.imageWidth, imported.imageHeight, authoredTask?.illustration ?? 'Рисунки и варианты из условия',
            image(escape(imported.image), imported.imageWidth, imported.imageHeight))
          .replace('<svg ', `<svg style="max-width:${imported.imageWidth}px" `)
        : '';
      const steps = [
        ['Твоё решение', 'Условие задачи', 'Выбери свой вариант ответа.'],
        ...explanation.map(([heading, message], stage) => [
          stage === explanation.length - 1 ? 'Ответ' : 'Шаг ' + (stage + 1), heading, message,
        ]),
      ];
      const formulas = explanation.map(([, message]) => equationsIn(message));
      const choice = answer === null ? '' : letters[answer];
      const description = `Условие и варианты задачи ${number} из оригинала.`;
      lessons.push({
        number,
        title: name,
        short: name,
        skill: '',
        answer,
        choices: native?.choices ?? ['', '', '', '', ''],
        choiceImages: native?.choiceImages,
        question: native?.question ?? '',
        conditionImage: figure?.[0],
        questionNote: note,
        legacyOriginal: true,
        hideIntroText: Boolean(native),
        showCompletedStep: true,
        points: i < 10 ? 3 : i < 20 ? 4 : 5,
        originalImage,
        steps,
      });
      scenes.push((step, frame) => {
        if (step === 0 && authoredTask?.crop) {
          const region = authoredTask.crop;
          const cropHeight = Math.round(720 * region[3] / Math.max(600, region[2]));
          const cropWidth = cropHeight * region[2] / region[3];
          return svg(720, cropHeight, authoredTask.illustration,
            crop(...card, region, (720 - cropWidth) / 2, 0, cropWidth, cropHeight));
        }
        if (step === 0 && native) return illustration;
        const final = step === steps.length - 1;
        const revealed = final ? choice : '';
        const answerLabel = revealed ? ` Ответ ${revealed}.` : '';
        if (step > 0) {
          const content = authoredTask?.draw
            ? authoredTask.draw(step, frame * 3, figure ?? card)
            : formulas[step - 1].length ? drawEquations(formulas[step - 1], frame * 5) : null;
          if (content) return workedScene(content, steps[step][1] + '. ' + steps[step][2] + answerLabel, revealed);
          if (native) {
            if (!revealed) return '';
            return workedScene([0, ''], description + answerLabel, revealed);
          }
        }
        return renderOriginal(...card, description + answerLabel, final ? marks[answer] : null, frame);
      });
    }

    archive[year] = {
      year,
      id: year + '-3-4',
      grades: [3, 4],
      label,
      answerLetters: letters,
      sources: {
        tasksUrl: `${source}/kenguru_${year}_class_3-4.pdf`,
        answersUrl: `${source}/kenguru_${year}_answers${[2017, 2018].includes(year) ? '-reviewed' : ''}.pdf`,
        solutionUrl: null,
      },
      lessons,
      scenes,
    };
  }
})();

